(() => {
  const form = document.getElementById('booking-form');
  const dateInput = document.getElementById('booking-date');
  const list = document.getElementById('booking-list');
  const empty = document.getElementById('empty-state');
  const confirmation = document.getElementById('confirmation');
  const error = document.getElementById('form-error');
  const count = document.getElementById('booking-count');
  const bookings = [];
  const today = new Date();
  const pad = n => String(n).padStart(2, '0');
  dateInput.min = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;

  function formatDate(value) {
    return new Intl.DateTimeFormat(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(`${value}T12:00:00`));
  }
  function formatTime(value) {
    const [h, m] = value.split(':');
    const d = new Date(); d.setHours(h, m);
    return new Intl.DateTimeFormat(undefined, { hour: 'numeric', minute: '2-digit' }).format(d);
  }
  function render() {
    list.querySelectorAll('[data-testid="booking"]').forEach(node => node.remove());
    empty.style.display = bookings.length ? 'none' : 'block';
    count.textContent = bookings.filter(b => !b.cancelled).length;
    bookings.forEach((booking, index) => {
      const card = document.createElement('article');
      card.dataset.testid = 'booking'; card.dataset.status = booking.cancelled ? 'cancelled' : 'active';
      card.className = `booking-card${booking.cancelled ? ' cancelled' : ''}`;
      card.innerHTML = `<div><div class="booking-type">${booking.type}</div><p class="booking-name" data-testid="booking-name-display"></p><p class="booking-meta">${formatDate(booking.date)} · ${formatTime(booking.time)} · ${booking.email}</p></div><div>${booking.cancelled ? '<span class="status-label">Cancelled</span>' : '<button class="cancel-button" data-testid="booking-cancel" type="button">Cancel</button>'}</div>`;
      card.querySelector('[data-testid="booking-name-display"]').textContent = booking.name;
      const cancel = card.querySelector('[data-testid="booking-cancel"]');
      if (cancel) cancel.addEventListener('click', () => { booking.cancelled = true; render(); });
      list.appendChild(card);
    });
  }
  form.addEventListener('submit', event => {
    event.preventDefault(); error.textContent = ''; confirmation.classList.remove('show');
    if (!form.checkValidity()) { form.reportValidity(); return; }
    const data = new FormData(form);
    const date = data.get('date');
    if (date < dateInput.min) { error.textContent = 'Please choose today or a future date.'; return; }
    bookings.push({ name: data.get('name').trim(), email: data.get('email').trim(), date, time: data.get('time'), type: data.get('type'), cancelled: false });
    render(); form.reset(); dateInput.min = `${today.getFullYear()}-${pad(today.getMonth() + 1)}-${pad(today.getDate())}`;
    confirmation.textContent = 'Booking confirmed — your appointment has been added to the schedule.';
    confirmation.classList.add('show');
  });
})();

